// Coverage labels are generated by the shared versioned Python contract.
export function replayCoverage(event, detail) {
  const value = detail?.completeness?.replayCoverage ?? event?.replayCoverage;
  return value?.version === 1 ? value : {code: "unknown", label: "棋谱覆盖待核验"};
}
export function resultQualityLabel(quality) {
  if (quality?.resultStatus === "disputed") return "比分待核 · 不计入胜负统计";
  if (quality?.replayable === false) return "棋谱无法复盘";
  if (quality?.finished === false) return "未完赛棋谱";
  return "";
}
